func hhAddBlock(hl *port.Cells, page int32, b int32, oblocks *port.Cells, olines *port.Cells, owords *port.Cells, feats *port.Cells) int32 {
	// Score OCR block `b` (an `oblocks` row of kind block): its words are those of the lines of its paragraphs. A component is the
	// mean of the words' measure weighted by their code points, over the words that have it; -1 for none. Answers the row.
	var r int32 = hhUpsert(hl, player.PlhOcrBlock(), page, b)
	var pr int32 = evidence.ObGet(oblocks, b, evidence.ObfFirst())
	var pend int32 = 0
	var li int32 = 0
	var lend int32 = 0
	var w int32 = 0
	var wend int32 = 0
	var f int32 = 0
	var wl int32 = 0
	var v int32 = 0
	var u int32 = 0
	var sc int32 = 0
	var s0 int32 = 0
	var n0 int32 = 0
	var s1 int32 = 0
	var n1 int32 = 0
	var s2 int32 = 0
	var n2 int32 = 0
	var s3 int32 = 0
	var n3 int32 = 0
	var s4 int32 = 0
	var n4 int32 = 0
	var s5 int32 = 0
	var n5 int32 = 0
	pend = pr + evidence.ObGet(oblocks, b, evidence.ObfCount())
	for pr < pend {
		if evidence.ObGet(oblocks, pr, evidence.ObfKind()) == evidence.ObParagraph() {
			li = evidence.ObGet(oblocks, pr, evidence.ObfFirst())
			lend = li + evidence.ObGet(oblocks, pr, evidence.ObfCount())
			for li < lend {
				w = evidence.OlGet(olines, li, evidence.LhFirst())
				wend = w + evidence.OlGet(olines, li, evidence.LhCount())
				for w < wend {
					f = evidence.OwGet(owords, w, evidence.HdFeat())
					if f >= 0 {
						wl = evidence.FeGet(feats, f, evidence.XoLength())
						if wl < 1 {
							wl = 1
						}
						v = evidence.FeGet(feats, f, evidence.XoKinInk())
						u = evidence.FeGet(feats, f, evidence.XoEngineInk())
						if u > v {
							v = u
						}
						if v >= 0 {
							s0 += wl * hhUp(v, HhInkBad(), HhInkOk())
							n0 += wl
						}
						v = evidence.FeGet(feats, f, evidence.XoImplausible())
						if v >= 0 {
							s1 += wl * (1000 - v)
							n1 += wl
						}
						v = evidence.FeGet(feats, f, evidence.XoScript())
						if v >= 0 {
							s2 += wl * (1000 - v)
							n2 += wl
						}
						v = evidence.FeGet(feats, f, evidence.XoBodyShare())
						if v >= 0 {
							s3 += wl * v
							n3 += wl
						}
						v = evidence.FeGet(feats, f, evidence.XoSeal())
						if v >= 0 {
							s4 += wl * (1000 - v)
							n4 += wl
						}
						v = evidence.FeGet(feats, f, evidence.XoArtifact())
						if v >= 0 {
							s5 += wl * (1000 - v)
							n5 += wl
						}
					}
					w += 1
				}
				li += 1
			}
		}
		pr += 1
	}
	player.HlSet(hl, r, HobInk(), hhPool(s0, n0))
	player.HlSet(hl, r, HobPlausible(), hhPool(s1, n1))
	player.HlSet(hl, r, HobScript(), hhPool(s2, n2))
	player.HlSet(hl, r, HobBody(), hhPool(s3, n3))
	player.HlSet(hl, r, HobSeal(), hhPool(s4, n4))
	player.HlSet(hl, r, HobArtifact(), hhPool(s5, n5))
	sc = HhOcrScore(player.HlGet(hl, r, HobInk()), player.HlGet(hl, r, HobPlausible()), player.HlGet(hl, r, HobScript()), player.HlGet(hl, r, HobBody()), player.HlGet(hl, r, HobSeal()), player.HlGet(hl, r, HobArtifact()))
	player.HlSet(hl, r, player.HlfScore(), sc)
	return r
}

func HlPage(page int32, cg *port.Cells, refs *port.Cells, fw *port.Cells, wd *port.Cells, etext *port.Cells, feats *port.Cells, oblocks *port.Cells, olines *port.Cells, owords *port.Cells, hl *port.Cells) int32 {
	// The page unit's call (see the head). The agreement of each (font, page) of the page and its scores; every OCR block's row.
	var nh int32 = player.HlCount(hl)
	var nb int32 = port.CellsLen(oblocks) / 16
	var r int32 = 0
	var b int32 = 0
	var rows int32 = 0
	var both int32 = 0
	var usea int32 = 0
	var agree int32 = 0
	hhCountAgreement(page, cg, refs, fw, wd, etext, hl)
	for r < nh {
		if (player.HlGet(hl, r, player.HlfKind()) == player.PlhFontPage()) && (player.HlGet(hl, r, player.HlfPage()) == page) {
			both = player.HlGet(hl, r, HlfBoth())
			agree = player.HlGet(hl, r, HlfAgree())
			if both > 0 {
				player.HlSet(hl, r, player.HlfAgreement(), (agree*1000)/both)
			} else {
				player.HlSet(hl, r, player.HlfAgreement(), -1)
			}
			usea = 0
			if both >= HhAgreeWords() {
				usea = 1
			}
			hhFontRescore(hl, r, usea)
		}
		r += 1
	}
	hhSetFonts(page, fw, feats, hl)
	for b < nb {
		if (evidence.ObGet(oblocks, b, evidence.ObfPage()) == page) && (evidence.ObGet(oblocks, b, evidence.ObfKind()) == evidence.ObBlock()) {
			hhAddBlock(hl, page, b, oblocks, olines, owords, feats)
			rows += 1
		}
		b += 1
	}
	return rows
}

func hhDocAgree(hl *port.Cells, font int32, from int32, want int32) int32 {
	// For font `font`: with `want` 0 the number of pages that have at least `agree-words` groups, with 1 the number of those under
	// `agree-min`, with 2 the groups with both candidates over the whole document, with 3 the agreeing ones.
	var n int32 = player.HlCount(hl)
	var i int32 = from
	var pages int32 = 0
	var low int32 = 0
	var both int32 = 0
	var agree int32 = 0
	for i < n {
		if (player.HlGet(hl, i, player.HlfKind()) == player.PlhFontPage()) && (player.HlGet(hl, i, player.HlfSubject()) == font) {
			both += player.HlGet(hl, i, HlfBoth())
			agree += player.HlGet(hl, i, HlfAgree())
			if player.HlGet(hl, i, HlfBoth()) >= HhAgreeWords() {
				pages += 1
				if player.HlGet(hl, i, player.HlfAgreement()) < HhAgreeMin() {
					low += 1
				}
			}
		}
		i += 1
	}
	if want == 0 {
		return pages
	}
	if want == 1 {
		return low
	}
	if want == 2 {
		return both
	}
	return agree
}

func HlDoc(feats *port.Cells, fw *port.Cells, hl *port.Cells) int32 {
	// The document unit's call: a font under `agree-min` on every page that has `agree-words` groups is unhealthy on every page.
	// Its rows' agreement is the page's own when the page has the groups and the document's (pooled) when it has not, and the
	// score is made again with it. The words' `xt` column 13 follow. Answers the rows changed.
	var n int32 = player.HlCount(hl)
	var i int32 = 0
	var font int32 = 0
	var changed int32 = 0
	var both int32 = 0
	var dag int32 = 0
	var j int32 = 0
	var ft int32 = 0
	var r int32 = 0
	var nw int32 = player.FwCount(fw)
	for i < n {
		if player.HlGet(hl, i, player.HlfKind()) == player.PlhFontPage() {
			font = player.HlGet(hl, i, player.HlfSubject())
			if (hhDocAgree(hl, font, 0, 0) > 0) && (hhDocAgree(hl, font, 0, 0) == hhDocAgree(hl, font, 0, 1)) {
				both = hhDocAgree(hl, font, 0, 2)
				dag = (hhDocAgree(hl, font, 0, 3) * 1000) / both
				if player.HlGet(hl, i, HlfBoth()) < HhAgreeWords() {
					player.HlSet(hl, i, player.HlfAgreement(), dag)
				}
				hhFontRescore(hl, i, 1)
				changed += 1
			}
		}
		i += 1
	}
	// every flow word: its row's score
	for j < nw {
		ft = port.CellsAt(fw, (j*24)+15)
		r = hhFind(hl, player.PlhFontPage(), port.CellsAt(fw, j*24), port.CellsAt(fw, (j*24)+19))
		if (ft >= 0) && (r >= 0) {
			evidence.FeSet(feats, ft, evidence.XtFontHealth(), player.HlGet(hl, r, player.HlfScore()))
		}
		j += 1
	}
	return changed
}

func hhImageOk(images *port.Cells, m int32) int32 {
	// 1 for a visible image placement at least `img-min` each way.
	if evidence.ImGet(images, m, evidence.MfVis()) != 0 {
		return 0
	}
	if (evidence.ImGet(images, m, evidence.MfX1()) - evidence.ImGet(images, m, evidence.MfX0())) < HhImgMin() {
		return 0
	}
	if (evidence.ImGet(images, m, evidence.MfY1()) - evidence.ImGet(images, m, evidence.MfY0())) < HhImgMin() {
		return 0
	}
	return 1
}

func hhRuleRegion(images *port.Cells, page int32, cx int32, cy int32) int32 {
	// The `images` row of the visible placement of the page that holds the point, else -1 (R0).
	var n int32 = port.CellsLen(images) / 20
	var m int32 = 0
	for m < n {
		if (evidence.ImGet(images, m, evidence.MfPage()) == page) && (hhImageOk(images, m) == 1) {
			if ((cx >= evidence.ImGet(images, m, evidence.MfX0())) && (cx < evidence.ImGet(images, m, evidence.MfX1()))) && ((cy >= evidence.ImGet(images, m, evidence.MfY0())) && (cy < evidence.ImGet(images, m, evidence.MfY1()))) {
				return m
			}
		}
		m += 1
	}
	return -1
}

func hhDev(dx int32, dy int32) int32 {
	// A rule's deviation from its axis in centi-degrees (signed, within +-1500 when it counts): 0 for a horizontal one; a
	// vertical one's from the vertical. -100000 for a slanted one that counts for neither.
	var a0 int32 = evidence.EvAngle(dx, dy)
	var a int32 = a0 - ((a0 / 18000) * 18000)
	if a <= HhAxis() {
		return a
	}
	if a >= (18000 - HhAxis()) {
		return a - 18000
	}
	if (a >= (9000 - HhAxis())) && (a <= (9000 + HhAxis())) {
		return a - 9000
	}
	return -100000
}

func hhRegionRow(hl *port.Cells, page int32, subject int32, witness int32, precision int32, skew int32, conf int32, nrules int32) int32 {
	var r int32 = hhUpsert(hl, player.PlhRegion(), page, subject)
	player.HlSet(hl, r, HrgWitness(), witness)
	player.HlSet(hl, r, HrgPrecision(), precision)
	player.HlSet(hl, r, HrgSkew(), skew)
	player.HlSet(hl, r, HrgConf(), conf)
	player.HlSet(hl, r, HrgRules(), nrules)
	player.HlSet(hl, r, player.HlfScore(), HhRegionScore(witness, precision, skew, conf))
	return r
}

func hhRegionMeasure(page int32, images *port.Cells, rules *port.Cells, region int32, want int32) int32 {
	// The tracer's measures of one region of a page: want 0 the number of its rules, 1 the mean rule confidence (-1 for none or
	// unknown), 2 the skew component (-1 with fewer than two axis-aligned rules): 1000 at a spread of the rules' deviations
	// of at most `skew-ok`, falling to 0 at `skew-bad`.
	var n int32 = port.CellsLen(rules) / 20
	var i int32 = 0
	var nr int32 = 0
	var csum int32 = 0
	var cn int32 = 0
	var axis int32 = 0
	var lo int32 = 100000
	var hi int32 = -100000
	var dx int32 = 0
	var dy int32 = 0
	var d int32 = 0
	var c int32 = 0
	for i < n {
		if evidence.RlGet(rules, i, evidence.RlfPage()) == page {
			dx = (evidence.RlGet(rules, i, evidence.RlfLx0()) + evidence.RlGet(rules, i, evidence.RlfLx1())) / 2
			dy = (evidence.RlGet(rules, i, evidence.RlfLy0()) + evidence.RlGet(rules, i, evidence.RlfLy1())) / 2
			if hhRuleRegion(images, page, dx, dy) == region {
				nr += 1
				c = evidence.RlGet(rules, i, evidence.RlfConf())
				if c >= 0 {
					csum += c
					cn += 1
				}
				d = hhDev(evidence.RlGet(rules, i, evidence.RlfLx1())-evidence.RlGet(rules, i, evidence.RlfLx0()), evidence.RlGet(rules, i, evidence.RlfLy1())-evidence.RlGet(rules, i, evidence.RlfLy0()))
				if d > -100000 {
					axis += 1
					if d < lo {
						lo = d
					}
					if d > hi {
						hi = d
					}
				}
			}
		}
		i += 1
	}
	if want == 0 {
		return nr
	}
	if want == 1 {
		return hhPool(csum, cn)
	}
	if axis < 2 {
		return -1
	}
	return hhDown(hi-lo, HhSkewOk(), HhSkewBad())
}

func HlRegions(page int32, images *port.Cells, rules *port.Cells, witness int32, precision int32, hl *port.Cells) int32 {
	// The page's graphics regions (see the head): R0 first (subject -1), then one row per visible placement of at least
	// `img-min`. An image region borrows R0's tracer precision and has no vector witness of its own.
	var ni int32 = port.CellsLen(images) / 20
	var m int32 = 0
	var rows int32 = 0
	var n0 int32 = hhRegionMeasure(page, images, rules, -1, 0)
	var prec int32 = precision
	hhRegionRow(hl, page, -1, witness, precision, hhRegionMeasure(page, images, rules, -1, 2), hhRegionMeasure(page, images, rules, -1, 1), n0)
	rows = 1
	for m < ni {
		if (evidence.ImGet(images, m, evidence.MfPage()) == page) && (hhImageOk(images, m) == 1) {
			hhRegionRow(hl, page, m, -1, prec, hhRegionMeasure(page, images, rules, m, 2), hhRegionMeasure(page, images, rules, m, 1), hhRegionMeasure(page, images, rules, m, 0))
			rows += 1
		}
		m += 1
	}
	return rows
}
